// Only price changes (not brand-new items) of at least 5%.
const MIN_PCT = 5;
const rows = $input.all().map(i => i.json).filter(r => r.priceStatus === 'changed' && Math.abs(r.priceChangePct ?? 0) >= MIN_PCT);
if (rows.length === 0) return [];
rows.sort((a, b) => Math.abs(b.priceChangePct) - Math.abs(a.priceChangePct));
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const tr = rows.slice(0, 50).map(r => {
  const arrow = r.priceChange < 0 ? '&#9660;' : '&#9650;';
  return `<tr><td>${esc(r.titleEn || r.title)}</td><td>${esc(r.shopName)}</td>` +
    `<td align="right">${r.previousPrice} &rarr; ${r.price} CNY</td>` +
    `<td align="right">${arrow} ${r.priceChangePct}%</td>` +
    `<td>${r.priceConverted ?? ''} ${esc(r.convertedCurrency)}</td><td><a href="${esc(r.url)}">open</a></td></tr>`;
}).join('');
const html = `<h3>${rows.length} Taobao price changes (&ge; ${MIN_PCT}%)</h3>` +
  `<table border="1" cellpadding="4" cellspacing="0"><tr><th>Product</th><th>Shop</th><th>Price (CNY)</th><th>Change</th><th>Now</th><th>Link</th></tr>${tr}</table>`;
return [{ json: { subject: `Taobao price alerts: ${rows.length} products changed`, html } }];
